"""Bahasa Indonesia — akhlak (virtues_001 … virtues_050)."""

T = {
"virtues_001": ("Menurut hadis yang diriwayatkan Imam al-Bukhari, apa yang harus dilakukan orang yang beriman kepada Allah dan hari Akhir dengan ucapannya?", ["Berkata baik atau diam", "Berbicara keras", "Tidak pernah berbicara", "Mengulang gosip"], "Nabi ﷺ bersabda: «Barang siapa beriman kepada Allah dan hari Akhir, hendaklah ia berkata baik atau diam.»"),
"virtues_002": ("Menurut hadis yang sama, siapa lagi yang harus dimuliakan orang beriman, selain tamunya?", ["Tetangganya", "Pedagangnya", "Saingannya", "Orang asing"], "Hadis itu berlanjut: «…dan barang siapa beriman kepada Allah dan hari Akhir, hendaklah ia memuliakan tetangganya.»"),
"virtues_003": ("Hadis yang sama juga menyebut memuliakan siapa, ketika ia datang ke rumah kita?", ["Tamu", "Hanya tetangga", "Pedagang", "Musafir asing yang jauh"], "Hadis lengkapnya berbunyi: «…barang siapa beriman kepada Allah dan hari Akhir, hendaklah ia memuliakan tamunya.»"),
"virtues_004": ("Menurut hadis sahih, iman seseorang tidak sempurna sampai ia mencintai bagi saudaranya apa yang ia cintai bagi…", ["dirinya sendiri", "hartanya", "keluarganya saja", "negerinya"], "Nabi ﷺ bersabda: «Tidaklah beriman salah seorang di antara kalian sampai ia mencintai bagi saudaranya apa yang ia cintai bagi dirinya sendiri.»"),
"virtues_005": ("Menurut hadis sahih, Muslim sejati adalah orang yang orang lain selamat dari lisan dan ___-nya.", ["tangan", "harta", "pandangan", "suara"], "Nabi ﷺ bersabda: «Muslim adalah orang yang kaum Muslimin selamat dari lisan dan tangannya.»"),
"virtues_006": ("Al-Qur'an memerintahkan berbakti kepada orang tua dan melarang mengucapkan kata kesal apa kepada mereka?", ["«Ah» (ungkapan kesal)", "«Tidak»", "«Cukup»", "«Tunggu»"], "Al-Qur'an menyeru kebaikan tertinggi kepada orang tua, bahkan melarang kata penghinaan yang paling ringan."),
"virtues_007": ("Dengan apa Al-Qur'an mengumpamakan gibah (membicarakan keburukan orang yang tidak hadir)?", ["Memakan daging saudaranya yang sudah mati", "Meminum air asin", "Berjalan dalam kegelapan", "Menabur di pasir"], "«Apakah ada di antara kamu yang suka memakan daging saudaranya yang sudah mati? Tentu kamu merasa jijik!»: begitu buruknya gibah."),
"virtues_008": ("Bagaimana Al-Qur'an menggambarkan hubungan antara orang-orang beriman?", ["Mereka bersaudara", "Mereka bersaing", "Mereka saling asing", "Mereka rekan bisnis"], "«Sesungguhnya orang-orang mukmin itu bersaudara, karena itu damaikanlah antara kedua saudaramu.»"),
"virtues_009": ("Apa yang dikatakan Al-Qur'an tentang mengolok-olok orang lain?", ["Dilarang: yang diolok-olok boleh jadi lebih baik daripada yang mengolok", "Boleh di antara teman", "Boleh jika lucu", "Khusus untuk penyair"], "«Janganlah suatu kaum mengolok-olok kaum yang lain, boleh jadi mereka lebih baik dari mereka.»"),
"virtues_010": ("Menurut Al-Qur'an, apa yang dijanjikan Allah bagi orang yang bersyukur?", ["Dia pasti akan menambah nikmat-Nya", "Umur panjang", "Kekayaan seketika", "Sebuah perjalanan"], "«Jika kamu bersyukur, niscaya Aku akan menambah nikmat kepadamu.»"),
"virtues_011": ("Menurut Al-Qur'an, bagaimana orang-orang yang sabar akan diberi pahala?", ["Dengan sempurna, tanpa batas", "Sekaligus", "Setelah empat puluh hari", "Sesuai kekayaannya"], "«Hanya orang-orang yang bersabarlah yang disempurnakan pahalanya tanpa batas.»"),
"virtues_012": ("«Makan dan minumlah, tetapi…»: bagaimana kelanjutan ayat ini?", ["Jangan berlebih-lebihan", "Jangan berbagi", "Jangan berbicara", "Jangan keluar"], "«Makan dan minumlah, tetapi jangan berlebihan. Sungguh, Allah tidak menyukai orang yang berlebih-lebihan.»"),
"virtues_013": ("Ayat apa, yang sering dibaca dalam khotbah Jumat, yang merangkum apa yang diperintahkan Allah?", ["«Allah memerintahkan berlaku adil dan berbuat kebajikan»", "«Allah memerintahkan berdagang»", "«Allah memerintahkan bepergian»", "«Allah memerintahkan diam»"], "«Sesungguhnya Allah menyuruh berlaku adil, berbuat kebajikan, dan memberi bantuan kepada kerabat…»: dibaca setiap Jumat."),
"virtues_014": ("Terhadap siapa surah Al-Muthaffifin dibuka dengan «Celakalah…»?", ["Orang yang curang dalam takaran dan timbangan", "Orang yang tidur", "Orang yang bepergian", "Orang yang diam"], "«Celakalah bagi orang-orang yang curang: yang apabila menerima takaran dari orang lain mereka minta dicukupkan, dan apabila menakar untuk orang lain mereka mengurangi.»"),
"virtues_015": ("Menurut surah Adh-Dhuha, bagaimana anak yatim dan orang yang meminta harus diperlakukan?", ["Tidak ditindas dan tidak dihardik", "Diabaikan", "Dikirim ke orang lain", "Diajak bicara nanti"], "«Maka terhadap anak yatim janganlah engkau berlaku sewenang-wenang, dan terhadap orang yang meminta janganlah engkau menghardik.»"),
"virtues_016": ("Bagaimana Al-Qur'an memerintahkan kita berbicara kepada manusia?", ["Dengan kata-kata yang baik", "Dengan suara sangat pelan", "Sesedikit mungkin", "Hanya kepada kerabat"], "«…dan bertutur katalah yang baik kepada manusia»: ucapan yang baik itu sendiri adalah ibadah."),
"virtues_017": ("Dalam nasihatnya kepada anaknya, apa yang dikatakan Luqman tentang berjalan dan kesombongan?", ["Jangan berjalan di bumi dengan angkuh", "Selalu berjalan cepat", "Hanya berjalan di malam hari", "Jangan pernah berjalan sendirian"], "«Janganlah memalingkan wajahmu dari manusia karena sombong, dan janganlah berjalan di bumi dengan angkuh.»"),
"virtues_018": ("Menurut hadis pertama dalam kumpulan al-Bukhari, dengan apa amal perbuatan dinilai?", ["Niat", "Hasil", "Kebiasaan", "Saksi"], "«Sesungguhnya amal itu tergantung pada niat, dan setiap orang hanya mendapatkan apa yang ia niatkan.»"),
"virtues_019": ("Menurut hadis dalam al-Bukhari, ke mana kejujuran (sidq) membawa?", ["Kepada kebajikan, dan kebajikan membawa ke surga", "Kepada kekayaan", "Kepada ketenaran", "Kepada kekuatan"], "«Kejujuran membawa kepada kebajikan, dan kebajikan membawa ke surga; dusta membawa kepada kejahatan, dan kejahatan membawa ke neraka.»"),
"virtues_020": ("Menurut hadis sahih, apa tiga tanda orang munafik?", ["Jika berbicara ia berdusta, jika berjanji ia mengingkari, jika dipercaya ia berkhianat", "Ia tidur, makan, dan berbicara terlalu banyak", "Ia bepergian, berdagang, dan bernyanyi", "Ia sedikit salat, sedikit puasa, dan sedikit membaca"], "«Tanda orang munafik ada tiga: jika berbicara ia berdusta, jika berjanji ia mengingkari, dan jika dipercaya ia berkhianat.»"),
"virtues_021": ("Seorang lelaki meminta nasihat kepada Nabi ﷺ; apa yang beliau ulangi kepadanya beberapa kali?", ["«Jangan marah»", "«Banyaklah bepergian»", "«Makanlah sedikit»", "«Bicaralah keras»"], "Lelaki itu berkata: «Nasihatilah aku.» Beliau menjawab: «Jangan marah.» Ia mengulang permintaannya, dan beliau mengulang: «Jangan marah.»"),
"virtues_022": ("Menurut Nabi ﷺ, siapa yang benar-benar kuat?", ["Orang yang mampu menguasai dirinya ketika marah", "Orang yang menang bergulat", "Orang yang memikul beban terberat", "Orang yang berlari paling cepat"], "«Orang yang kuat bukanlah yang menang bergulat; orang yang kuat adalah yang mampu menguasai dirinya ketika marah.»"),
"virtues_023": ("Menurut hadis dalam al-Bukhari, rasa malu (haya') adalah bagian dari apa?", ["Iman", "Kelemahan", "Kekayaan", "Sifat pemalu yang tercela"], "Melihat seorang lelaki menegur saudaranya karena rasa malunya, Nabi ﷺ bersabda: «Biarkan dia, karena rasa malu adalah bagian dari iman.»"),
"virtues_024": ("Apa yang dikatakan Nabi ﷺ kepada lelaki yang berbangga tidak pernah mencium seorang pun dari sepuluh anaknya?", ["«Barang siapa tidak menyayangi, ia tidak akan disayangi»", "«Engkau benar»", "«Anak-anak tidak penting»", "«Itu urusan pribadi»"], "Nabi ﷺ biasa mencium cucu-cucunya; kepada Al-Aqra' yang heran, beliau menjawab: «Man la yarham la yurham.»"),
"virtues_025": ("Menurut hadis dalam al-Bukhari, karena amal apa seorang lelaki diampuni?", ["Karena memberi minum anjing yang kehausan", "Karena membangun sumur", "Karena menanam pohon", "Karena mengusir serigala"], "Lelaki itu turun ke sumur, mengisi sepatunya dengan air, dan memberikannya kepada anjing yang terengah-engah kehausan; Allah mengampuninya."),
"virtues_026": ("Menurut hadis sahih, mengapa seorang perempuan disiksa?", ["Karena mengurung kucing tanpa memberinya makan atau membiarkannya mencari makan", "Karena menjual kucing", "Karena mengusir kucing dari rumahnya", "Karena memelihara terlalu banyak kucing"], "«Seorang perempuan disiksa karena seekor kucing yang ia kurung sampai mati: ia tidak memberinya makan dan tidak membiarkannya makan dari binatang-binatang bumi.»"),
"virtues_027": ("Tentang siapa Nabi ﷺ bersabda bahwa Jibril terus berpesan kepadanya sampai beliau mengira ia akan dijadikan ahli waris?", ["Tetangga", "Tamu", "Anak yatim", "Musafir"], "«Jibril terus berpesan kepadaku tentang tetangga, sampai aku mengira ia akan menjadikannya ahli waris.»"),
"virtues_028": ("Menurut hadis dalam al-Bukhari, berapa hak seorang Muslim atas Muslim lainnya?", ["Lima", "Tiga", "Tujuh", "Sepuluh"], "«Menjawab salam, menjenguk yang sakit, mengantar jenazah, memenuhi undangan, dan mendoakan orang yang bersin.»"),
"virtues_029": ("Ketika ditanya «Islam yang bagaimana yang paling baik?», apa jawaban Nabi ﷺ?", ["Memberi makan dan mengucapkan salam kepada yang dikenal maupun yang tidak dikenal", "Membangun masjid", "Banyak bepergian", "Sedikit berbicara"], "«Memberi makan, dan mengucapkan salam kepada orang yang engkau kenal maupun yang tidak engkau kenal.»"),
"virtues_030": ("Dengan apa Nabi ﷺ mengumpamakan orang-orang beriman dalam kasih sayang dan saling menolong mereka?", ["Satu tubuh: jika satu anggota sakit, seluruh tubuh ikut terjaga dan demam", "Sebuah hutan", "Sebuah kafilah", "Sebuah kawanan"], "«Perumpamaan orang-orang beriman dalam saling mencintai, menyayangi, dan mengasihi adalah seperti satu tubuh.»"),
"virtues_031": ("Menurut Nabi ﷺ, apa «ucapan yang paling dusta»?", ["Prasangka (zhann)", "Syair", "Gurauan", "Diam"], "«Jauhilah prasangka, karena prasangka adalah ucapan yang paling dusta.»"),
"virtues_032": ("Menurut hadis sahih, paling lama berapa hari seorang Muslim boleh mendiamkan saudaranya?", ["Tiga hari", "Tujuh hari", "Sebulan", "Setahun"], "«Tidak halal bagi seorang Muslim mendiamkan saudaranya lebih dari tiga malam… dan yang terbaik di antara keduanya adalah yang lebih dahulu mengucapkan salam.»"),
"virtues_033": ("Menurut Nabi ﷺ, apa nilai setiap kebaikan, sekecil apa pun?", ["Sedekah", "Tidak dihitung", "Senilai satu dinar", "Menggantikan salat"], "«Setiap kebaikan adalah sedekah.»"),
"virtues_034": ("Menurut hadis dalam Sahih Muslim, apa cabang iman yang paling rendah?", ["Menyingkirkan gangguan dari jalan", "Membangun masjid", "Membaca satu juz", "Berpuasa sehari"], "«Iman memiliki tujuh puluh sekian cabang: yang tertinggi adalah 'la ilaha illallah', yang terendah adalah menyingkirkan gangguan dari jalan; dan rasa malu adalah cabang iman.»"),
"virtues_035": ("Menurut hadis dalam Sahih Muslim, kesucian (thaharah) adalah…?", ["Setengah dari iman", "Sepertiga dari iman", "Sepersepuluh dari iman", "Tidak berkaitan dengan iman"], "«Kesucian adalah setengah dari iman, dan 'alhamdulillah' memenuhi timbangan.»"),
"virtues_036": ("Nabi ﷺ bersabda: «Agama adalah nasihat (ketulusan)»: kepada siapa?", ["Kepada Allah, Kitab-Nya, Rasul-Nya, para pemimpin, dan seluruh kaum Muslimin", "Hanya kepada diri sendiri", "Kepada orang kaya", "Kepada orang asing"], "Mereka bertanya: «Kepada siapa?» Beliau menjawab: «Kepada Allah, Kitab-Nya, Rasul-Nya, para pemimpin kaum Muslimin, dan kaum Muslimin pada umumnya.»"),
"virtues_037": ("Menurut hadis dalam Sahih Muslim, apa yang dilihat Allah pada hamba-hamba-Nya?", ["Hati dan amal mereka", "Rupa mereka", "Harta mereka", "Jumlah mereka"], "«Allah tidak melihat tubuh dan rupa kalian, tetapi Dia melihat hati dan amal kalian.»"),
"virtues_038": ("Menurut hadis dalam Sahih Muslim, apa yang dilakukan Allah bagi orang yang melapangkan kesusahan dunia seorang mukmin?", ["Dia melapangkan kesusahannya pada hari Kiamat", "Dia menjadikannya kaya", "Dia memberinya umur panjang", "Dia menjadikannya terkenal"], "«Barang siapa melapangkan satu kesusahan dunia dari seorang mukmin, Allah akan melapangkan darinya satu kesusahan pada hari Kiamat.»"),
"virtues_039": ("Menurut Nabi ﷺ, apa yang dilakukan Allah bagi orang yang menempuh jalan untuk mencari ilmu?", ["Dia memudahkan baginya jalan menuju surga", "Dia membebaskannya dari salat", "Dia menjadikannya kaya", "Dia menjadikannya raja"], "«Barang siapa menempuh jalan untuk mencari ilmu, Allah akan memudahkan baginya jalan menuju surga.»"),
"virtues_040": ("Menurut hadis dalam al-Bukhari, siapa «yang terbaik di antara kalian»?", ["Orang yang mempelajari Al-Qur'an dan mengajarkannya", "Orang yang paling pandai bicara", "Orang yang paling banyak harta", "Orang yang paling banyak bepergian"], "«Sebaik-baik kalian adalah orang yang mempelajari Al-Qur'an dan mengajarkannya.»"),
"virtues_041": ("Bagaimana Nabi ﷺ mendefinisikan kesombongan (kibr)?", ["Menolak kebenaran dan meremehkan manusia", "Memakai pakaian bagus", "Menyukai sepatu yang indah", "Berjalan cepat"], "Kepada lelaki yang menyukai pakaian bagus beliau bersabda: «Allah itu indah dan menyukai keindahan. Kesombongan adalah menolak kebenaran dan meremehkan manusia.»"),
"virtues_042": ("Menurut hadis dalam al-Bukhari, dua nikmat apa yang banyak orang tertipu di dalamnya?", ["Kesehatan dan waktu luang", "Uang dan ketenaran", "Kekuatan dan kecantikan", "Keluarga dan teman"], "«Ada dua nikmat yang banyak manusia tertipu di dalamnya: kesehatan dan waktu luang.»"),
"virtues_043": ("Lengkapi hadis ini: «Seorang mukmin tidak disengat dua kali…»", ["«…dari lubang yang sama»", "«…oleh kalajengking yang sama»", "«…pada hari yang sama»", "«…oleh lebah yang sama»"], "«La yuldaghul-mu'minu min juhrin wahidin marratain»: orang beriman belajar dari kesalahannya."),
"virtues_044": ("Dengan apa Nabi ﷺ mengumpamakan teman yang baik, berlawanan dengan pandai besi?", ["Penjual minyak kesturi", "Tukang roti", "Penggembala", "Pedagang kain"], "«Teman yang baik seperti pembawa minyak kesturi: ia memberimu, atau engkau membeli darinya, atau engkau mencium harumnya; teman yang buruk seperti peniup api pandai besi.»"),
"virtues_045": ("Menurut hadis dalam al-Bukhari, atas apa setiap kita bertanggung jawab «seperti penggembala»?", ["Atas orang-orang yang berada dalam tanggungan kita", "Atas cuaca", "Atas bintang-bintang", "Atas panen orang lain"], "«Setiap kalian adalah pemimpin, dan setiap kalian bertanggung jawab atas yang dipimpinnya»: penguasa atas rakyatnya, suami atas keluarganya, istri atas rumah tangganya."),
"virtues_046": ("Menurut Al-Qur'an, apa yang terjadi jika keburukan ditolak dengan yang lebih baik?", ["Orang yang tadinya musuh menjadi seperti teman yang setia", "Keburukan lenyap dari bumi", "Seseorang menjadi kaya", "Tidak ada yang berubah"], "«Tolaklah kejahatan dengan cara yang lebih baik, sehingga orang yang ada rasa permusuhan antara kamu dan dia akan seperti teman yang setia» (41:34)."),
"virtues_047": ("Bagaimana «hamba-hamba Tuhan Yang Maha Pengasih» menjawab orang jahil yang memancing mereka, menurut surah Al-Furqan?", ["Mereka mengucapkan: «Salam!»", "Mereka menjawab dengan marah", "Mereka mengolok-oloknya", "Mereka memukulnya"], "«Hamba-hamba Tuhan Yang Maha Pengasih adalah orang-orang yang berjalan di bumi dengan rendah hati, dan apabila orang-orang jahil menyapa mereka, mereka mengucapkan: Salam!» (25:63)."),
"virtues_048": ("Apa yang dikatakan Al-Qur'an tentang janji?", ["«Penuhilah janji, sesungguhnya janji itu pasti diminta pertanggungjawabannya»", "«Janji tidak mengikat siapa pun»", "«Hanya berjanjilah kepada orang kaya»", "«Jangan pernah berjanji»"], "«Dan penuhilah janji, karena janji itu pasti diminta pertanggungjawabannya» (17:34)."),
"virtues_049": ("Tentang siapa Al-Qur'an mengatakan bahwa mereka «saudara-saudara setan»?", ["Orang yang menghambur-hamburkan harta", "Para musafir", "Para pedagang", "Para penyair"], "«Sesungguhnya orang-orang yang pemboros itu adalah saudara setan, dan setan itu sangat ingkar kepada Tuhannya» (17:27)."),
"virtues_050": ("Apa «dua kalimat yang ringan di lisan, berat di timbangan, dan dicintai Yang Maha Pengasih»?", ["«Subhanallahi wa bihamdih, subhanallahil 'azhim»", "«Allahu akbar, alhamdulillah»", "«La ilaha illallah, Muhammadur rasulullah»", "«Bismillah, masya Allah»"], "«Dua kalimat yang ringan di lisan, berat di timbangan, dicintai Yang Maha Pengasih: Mahasuci Allah dan segala puji bagi-Nya; Mahasuci Allah Yang Mahaagung.»"),
}
